void TIM3_IRQHandler(void) {
  if (TIM3->SR & (1 << 0)) {
    TIM3->SR &= ~(1 << 0);  // Clear update interrupt flag
    Kobuki_Read(&kobuki);
    Ultrasonic_Detect(&object);
    Kobuki_Update_LEDs(led_1, led_2);

    // added to stop kobuki if wheel drop
    if ((kobuki.button & BUTTON_1_STOP) || kobuki.wheeldrop != 0) {
      Kobuki_Drive(STOP);
      current_state = IDLE;
      return;
    }

    // right cliff/bumper
    if (kobuki.cliff == 0x01 || kobuki.bumper == 0x01) {
      Kobuki_Drive(STOP);
      Kobuki_Rotate_Angle_Setpoint(kobuki.angle, 5);
      while (kobuki.rotation_complete == false) {
        Kobuki_Rotate_Angle(kobuki.angle);
      }
      // left cliff/bumper
    } else if (kobuki.cliff == 0x02 || kobuki.bumper == 0x02) {
      Kobuki_Drive(STOP);
      Kobuki_Rotate_Angle_Setpoint(kobuki.angle, -5);
      while (kobuki.rotation_complete == false) {
        Kobuki_Rotate_Angle(kobuki.angle);
      }

      // front cliff/bumper
    } else if (kobuki.cliff == 0x04 || kobuki.bumper == 0x04) {
      Kobuki_Drive(STOP);
      current_state = IDLE;
    }

    // main FSM
    switch (current_state) {
      case IDLE:
        // initialize all states
        Kobuki_Drive(STOP);
        if (kobuki.button & BUTTON_0_START) {
          current_search_state = SEARCH_IDLE;
          current_pathfind_state = PATHFIND_IDLE;
          current_storage_state = STORAGE_IDLE;
          current_deposit_state = DEPOSIT_IDLE;
          search_complete = false;
          pathfind_complete = false;
          deposit_complete = false;
          current_state = SEARCH;
        }
        break;
      case SEARCH:
        if (!search_complete) {
          searchFSM();
        } else
          current_state = PATHFIND;
        // TODO: check if double setting current_state to PATHFIND is fine, this
        // is the same issue with other states
        break;
      case PATHFIND:
        if (pathfind_complete) {
          current_state = STORAGE;
        } else
          Pathfind_FSM();
        break;
      case STORAGE:
        if (!storage_complete) {
          storageFSM();
        } else {
          current_state = DEPOSIT;
        }
        break;
      case DEPOSIT:
        if (deposit_complete) {
          Kobuki_Drive(STOP);
          current_state = IDLE;
        } else {
          Deposit_FSM();
        }
        break;
      // case ORIENT:, we dont have this state in our design
      default:
        Kobuki_Drive(STOP);
        current_state = IDLE;
        break;
    }
    // searchFSM();//test
    // Pathfind_FSM();//test
    // storageFSM();//test
  }
}

